def txt(s, x, y, fill=WHITE, size=24, bold=False, centered=False,
        max_w=None, color=None):
    """Render text. centered=True = horizontal center at x. max_w = wrap width."""
    f = fnt(size, bold)
    fc = color or fill

    # Normalize: split on \n, then word-wrap each resulting line
    raw_lines = s.split('\n')
    wrapped_lines = []
    for raw in raw_lines:
        if max_w:
            words = raw.split()
            lines, cur = [], ""
            for w_ in words:
                test = (cur + " " + w_).strip()
                if draw.textlength(test, font=f) <= max_w:
                    cur = test
                else:
                    if cur:
                        lines.append(cur)
                    cur = w_
            if cur:
                lines.append(cur)
            wrapped_lines.extend(lines if lines else [""])
        else:
            wrapped_lines.append(raw)

    lh = size * 1.15
    total = len(wrapped_lines) * lh
    start_y = y - total / 2 if centered else y
    for i, l in enumerate(wrapped_lines):
        if centered:
            xc = x - draw.textlength(l, font=f) / 2
        else:
            xc = x
        draw.text((xc, start_y + i * lh), l, fill=fc, font=f)
    return total

